8	
9	const PICKERS_NAMESPACE: &str = "pickers_v2";
10	
11	pub(crate) fn store_shape_for_this_layout(
12	    picker_delegate: &'static str,
13	    preview_layout: Option<preview::Layout>,
14	    shape: shape::Centered,
15	    window: &ui::Window,
16	    cx: &App,
17	) {
18	    let shape = PickerConfig::from_centered(shape, window);
19	
20	    let kvp = KeyValueStore::global(cx);
21	    db::write_and_log(cx, async move || {
22	        kvp.scoped(PICKERS_NAMESPACE)
23	            .write(
24	                shape_key(picker_delegate, preview_layout),
25	                serde_json::to_string(&shape).context("Could not serialize size of picker")?,
26	            )
27	            .await?;
28	        // Must be written after the shape or loading can break
29	        // if this future is ever cancelled.
30	        kvp.scoped(PICKERS_NAMESPACE)
31	            .write(
32	                last_layout_key(picker_delegate),
33	                layout_as_str(preview_layout).to_string(),
34	            )
35	            .await
36	    });
37	}
38	
39	/// Persist the last-used preview layout without touching the stored shape.
40	///
41	/// Changing the preview position (e.g. right/below/hidden) without resizing
42	/// must still be remembered, so this is called whenever the layout changes.
43	pub(crate) fn store_last_layout(
44	    picker_delegate: &'static str,
45	    preview_layout: Option<preview::Layout>,
46	    cx: &App,
47	) {
48	    let kvp = KeyValueStore::global(cx);
49	    db::write_and_log(cx, async move || {
50	        kvp.scoped(PICKERS_NAMESPACE)
51	            .write(
52	                last_layout_key(picker_delegate),
53	                layout_as_str(preview_layout).to_string(),
